const scenarios=[...new Set(o.scenario.split(',').flatMap(s=>s==='all'?['load','idle','scroll','sweep']:[s]))];for(const s of scenarios)if(!['load','idle','scroll','sweep','pause','scrollback','interact'].includes(s))throw Error('unknown scenario '+s);
