const ctxOpts=o.device?{...devices[o.device],reducedMotion:'no-preference'}:{viewport:{width:Number(o.width),height:820},deviceScaleFactor:Number(o.dpr),reducedMotion:'no-preference'};
const DPR=ctxOpts.deviceScaleFactor||1;
