const G=[['birds','.bird,.birds'],['bees','.bee,.bees'],['bugs','.bug,.bugs'],['network','.net'],['leaves','.leaf,.leaftag'],['scene','.tree,.scene,.stage']];
const grp=e=>{for(const [n,s] of G)if(e.closest&&e.closest(s))return n;return 'other';};
const mtc=new WeakMap(),isMT=a=>{let v=mtc.get(a);if(v===undefined){v=a.effect?.getKeyframes().some(k=>Object.keys(k).some(p=>!SKIP.includes(p)&&!CC.has(p)))??false;mtc.set(a,v);}return v;};
