const metrics=async cdp=>Object.fromEntries((await cdp.send('Performance.getMetrics')).metrics.map(m=>[m.name,m.value]));
const procCpu=async b=>{if(!b)return null;const r={};for(const p of (await b.send('SystemInfo.getProcessInfo')).processInfo){const t=/gpu/i.test(p.type)?'gpu':p.type;if(['gpu','browser','renderer'].includes(t))r[t]=(r[t]||0)+p.cpuTime;}/* service processes (network, tracing) are measurement overhead or noise */return r;};
